interface TodoRepository {
  create(todo: Todo): Promise<void>;
  findAll(): Promise<Todo[]>;
  findById(id: string): Promise<Todo | null>;
  updateStatus(id: string, completed: boolean): Promise<void>;
  delete(id: string): Promise<void>;
  search(keyword: string): Promise<Todo[]>;
  findByStatus(completed: boolean): Promise<Todo[]>;
  findByUserId(userId: string): Promise<Todo[]>;
}

class PostgresTodoRepository implements TodoRepository {
  constructor(private db: typeof db) {}

  async create(todo: Todo): Promise<void> {
    const query = 'INSERT INTO todos (id, title, description, completed, created_at) VALUES ($1, $2, $3, $4, $5)';
    await this.db.query(query, [todo.id, todo.title, todo.description, todo.completed, todo.createdAt]);
  }

  async findAll(): Promise<Todo[]> {
    const query = 'SELECT * FROM todos ORDER BY created_at DESC';
    const rows = await this.db.query(query);
    return rows as Todo[];
  }

  async findById(id: string): Promise<Todo | null> {
    const query = 'SELECT * FROM todos WHERE id = $1';
    const rows = await this.db.query(query, [id]);
    return rows.length === 0 ? null : rows[0] as Todo;
  }

  async updateStatus(id: string, completed: boolean): Promise<void> {
    const query = 'UPDATE todos SET completed = $1 WHERE id = $2';
    await this.db.query(query, [completed, id]);
  }

  async delete(id: string): Promise<void> {
    const query = 'DELETE FROM todos WHERE id = $1';
    await this.db.query(query, [id]);
  }

  async search(keyword: string): Promise<Todo[]> {
    const query = 'SELECT * FROM todos WHERE title LIKE $1 OR description LIKE $1';
    const pattern = `%${keyword}%`;
    const rows = await this.db.query(query, [pattern]);
    return rows as Todo[];
  }

  async findByStatus(completed: boolean): Promise<Todo[]> {
    const query = 'SELECT * FROM todos WHERE completed = $1';
    const rows = await this.db.query(query, [completed]);
    return rows as Todo[];
  }

  async findByUserId(userId: string): Promise<Todo[]> {
    const query = 'SELECT t.* FROM todos t JOIN user_todos ut ON t.id = ut.todo_id WHERE ut.user_id = $1';
    const rows = await this.db.query(query, [userId]);
    return rows as Todo[];
  }
}

const todoRepository = new PostgresTodoRepository(db);

export async function getAllTodos(): Promise<Todo[]> {
  return todoRepository.findAll();
}

export async function getTodoById(id: string): Promise<Todo | null> {
  return todoRepository.findById(id);
}

